  echo -n "$addr -> "
  # Find the nearest symbol below this address
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk -v addr="$addr" '
    BEGIN { target = strtonum(addr); best_name = "??"; best_addr = 0; best_size = 0 }
    {
      a = strtonum("0x" $1);
      if ($3 != "" && a <= target && a > best_addr) {
        best_addr = a;
        best_name = $3;
        best_size = $2 != "" ? $2 : 0;
      }
    }
    END { printf "%s+0x%x\n", best_name, target - best_addr }
  '
done

