{"command": "cd /tmp/sv-4e0450b8fc374213ae758ee66d681d4a && python3 << 'EOF'
import subprocess, re

# Get all defined FUNC symbols with their addresses and sizes
result = subprocess.run(['readelf', '-sW', 'libmonosgen-2.0.so'], capture_output=True, text=True)
symbols = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 8 and 'FUNC' in parts:
        addr = int(parts[1], 16)
        size = int(parts[2])
        name = parts[7]
        if addr > 0:
            symbols.append((addr, size, name))

symbols.sort(key=lambda x: x[0])

# Addresses to resolve
addrs = {
    '0x222098': ('Thread 7020 (main) #01', 0x222098),
    '0x2241ac': ('Thread 7020 (main) #02', 0x2241ac),
    '0x1abc80': ('Thread 7020 (main) #03', 0x1abc80),
    '0x16de04': ('Thread 7020 (main) #04', 0x16de04),
    '0x2f4b20': ('Thread 7046 (SGen worker) #02', 0x2f4b20),
    '0x2f4c84': ('Thread 7046 (SGen worker) #03', 0x2f4c84),
    '0x2c1a40': ('Thread 7048 (Finalizer) #02', 0x2c1a40),
}

for label_key, (desc, target) in addrs.items():
    # Find symbol containing or nearest below
    best = None
    for addr, size, name in symbols:
        if addr <= target:
            best = (addr, size, name)
        else:
            break

    if best:
        addr, size, name = best
        offset = target - addr
        in_bounds = "(within function)" if size > 0 and offset < size else f"(offset 0x{offset:x}, size 0x{size:x})" if size > 0 else f"(+0x{offset:x})"
        print(f"{desc}: {label_key} -> {name}+0x{offset:x} {in_bounds}")
    else:
        print(f"{desc}: {label_key} -> ??")
EOF", "description": "Symbolicate with proper nearest-symbol lookup"}
